function acceptIntent(event, origin, sender, receive) {
  if (event.origin !== origin || event.source !== sender) return false;
  receive(event.data);
  return true;
}

function attachBridge(host, frame, origin, receive) {
  const listener = event => acceptIntent(event, origin, frame.contentWindow, receive);
  host.addEventListener('message', listener);
  return () => host.removeEventListener('message', listener);
}

module.exports = { acceptIntent, attachBridge };

