const test = require('node:test');
const assert = require('node:assert/strict');
const { acceptIntent } = require('./bridge');

test('accept configured sender', () => {
  const frame = {}; const received = [];
  assert.equal(acceptIntent({origin: 'https://portal.example.invalid', source: frame, data: 'trade'}, 'https://portal.example.invalid', frame, x => received.push(x)), true);
  assert.deepEqual(received, ['trade']);
});

test('reject another origin', () => {
  const frame = {}; const received = [];
  assert.equal(acceptIntent({origin: 'https://other.example.invalid', source: frame, data: 'trade'}, 'https://portal.example.invalid', frame, x => received.push(x)), false);
  assert.deepEqual(received, []);
});

