const host = {
 addEventListener(type, callback) { assert.equal(type, 'message'); listener = callback; },
 removeEventListener() {}
};
attachBridge(host, {contentWindow: designated}, 'https://portal.example.invalid', value => received.push(value));
listener({origin: 'https://portal.example.invalid', source: other, data: {intent: 'untrusted'}});
assert.deepEqual(received, [], 'Messages from another source frame must not reach the receiver');
